// Generates TypeScript types from the published OpenAPI contracts (repo-root contracts/openapi).
// The contracts are the source of truth: never edit src/generated by hand; rerun `npm run codegen`.
import { readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve, basename } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import openapiTS, { astToString } from "openapi-typescript";

const here = dirname(fileURLToPath(import.meta.url));
const contracts = resolve(here, "../../../../contracts/openapi");
const out = resolve(here, "../src/generated");
mkdirSync(out, { recursive: true });

const groups = ["public", "authzen"];
const written = [];
for (const group of groups) {
  for (const file of readdirSync(join(contracts, group)).filter((f) => f.endsWith(".json"))) {
    const name = (group === "authzen" ? "authzen-" : "") + basename(file, ".json");
    const ast = await openapiTS(pathToFileURL(join(contracts, group, file)));
    const header = `// GENERATED from contracts/openapi/${group}/${file} by packages/api-client/openapi/codegen.mjs. Do not edit.\n`;
    writeFileSync(join(out, `${name}.ts`), header + astToString(ast));
    written.push(name);
  }
}
// The standalone TypeScript SDK (sdks/typescript, no runtime dependencies) ships the same generated types for the /v2 facades it calls.
const sdkOut = resolve(here, "../../../../sdks/typescript/src/generated");
mkdirSync(sdkOut, { recursive: true });
for (const name of ["credentials", "evidence", "verification"]) {
  const ast = await openapiTS(pathToFileURL(join(contracts, "public", `${name}.json`)));
  const header = `// GENERATED from contracts/openapi/public/${name}.json by frontend/packages/api-client/openapi/codegen.mjs. Do not edit.
`;
  writeFileSync(join(sdkOut, `${name}.ts`), header + astToString(ast));
}
console.log(`generated ${written.length} contract types: ${written.join(", ")}`);
